/**
 * User Story 5 - Navigate and restructure with the Document Tree (T082).
 *
 * Runs against the real core (`MFBE_CORE_BIN=../build/linux-core-debug/bin/mfbe-core`) on a
 * 300-section book generated by `tests/fixtures/gen-sections.py`; skipped in core-less mode or
 * without python3.
 *
 * Scenarios (spec.md US5):
 *  1. selecting a tree node scrolls/selects the element in the Body (moving the section window
 *     of the large book) and the tree follows the Body caret;
 *  2. Move Right / Move With Children / Move Left / Merge / Delete from the toolbar and the
 *     context menu change the structure, each as one undo entry, and the saved book validates;
 *  3. View Source opens the Source view positioned on the element.
 */

import { spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import type { Locator, Page } from '@playwright/test';

import { expect, test, waitForBook, type CoreHandle, type RpcCallError } from './fixtures/core';

const REPO_ROOT = fileURLToPath(new URL('../../..', import.meta.url));
const GENERATOR = path.join(REPO_ROOT, 'tests', 'fixtures', 'gen-sections.py');

interface ValidationJson {
  errorCount: number;
  warningCount: number;
  issues: { severity: string; code: string; params: Record<string, unknown>; line?: number }[];
}

async function supportsDocuments(core: CoreHandle): Promise<boolean> {
  if (!core.hasCore) return false;
  return core
    .rpc('doc.recent')
    .then(() => true)
    .catch((error: RpcCallError) => error.code !== -32601);
}

async function openBook(core: CoreHandle, page: Page, file: string): Promise<void> {
  await core.openApp(page);
  await expect(page.getByTestId('status-message')).toHaveText('Ready');
  await core.enqueueDialog('dialog.openFile', { paths: [file] });
  await page.getByTestId('menu-file').click();
  await page.getByTestId('menu-file-open').click();
  await waitForBook(page, file);
  await expect(page.getByTestId('body-editor')).toHaveAttribute('contenteditable', 'true');
  await expect(page.getByTestId('tree-content')).toHaveAttribute('data-section-count', /\d+/);
}

/** The tree row of the section with the XML id `s<N>`; the tree may still be re-rendering. */
async function rowOfSection(page: Page, number: number): Promise<Locator> {
  const message = `section ${number} not found in the tree`;
  const found = { row: await findSectionRow(page, number) };
  if (!found.row) {
    await expect
      .poll(
        async () => {
          found.row = await findSectionRow(page, number);
          return found.row !== null;
        },
        { message, timeout: 30_000 },
      )
      .toBe(true);
  }
  if (!found.row) throw new Error(message);
  return found.row;
}

/** One pass over the virtual list for the section `s<N>`; null when it is not rendered. */
async function findSectionRow(page: Page, number: number): Promise<Locator | null> {
  const tree = page.getByTestId('tree-content');
  // Rows are virtualised: scroll through the list until the caption is rendered, then address
  // the row by its stable testid (`tree-row-<nodeId>`).
  const escaped = sectionNumberOf(number).replace(/\./g, '\\.');
  const caption = new RegExp(`^(Part|Chapter|Scene|Fragment) ${escaped}$`);
  await tree.evaluate((element) => {
    element.scrollTop = 0;
  });
  for (let attempt = 0; attempt < 80; attempt += 1) {
    // One atomic lookup in the page: the virtualised rows may unmount between two calls.
    const testId = await tree.evaluate((element, source) => {
      const re = new RegExp(source);
      for (const span of element.querySelectorAll('.mfbe-tree-row-caption')) {
        if (re.test(span.textContent ?? '')) return span.parentElement?.getAttribute('data-testid');
      }
      return null;
    }, caption.source);
    if (testId) return page.getByTestId(testId);
    const atEnd = await tree.evaluate((element) => {
      const before = element.scrollTop;
      element.scrollTop += Math.max(100, element.clientHeight - 44);
      return element.scrollTop === before;
    });
    if (atEnd) break;
    await page.waitForTimeout(40);
  }
  return null;
}

let numbering: Map<number, string> | null = null;

/** `s<N>` -> hierarchical number ("3.2.1") from the fixture text. */
function sectionNumberOf(number: number): string {
  const value = numbering?.get(number);
  if (!value) throw new Error(`unknown section ${number}`);
  return value;
}

function indexFixture(text: string): Map<number, string> {
  const map = new Map<number, string>();
  for (const match of text.matchAll(
    /<section id="s(\d+)">\s*<title><p>(?:Part|Chapter|Scene|Fragment) ([\d.]+)<\/p><\/title>/g,
  )) {
    map.set(Number(match[1]), match[2]!);
  }
  return map;
}

/** Nesting depth (1 = top level) and parent id of every `s<N>` section in an FB2 text. */
function structureOf(text: string): Map<string, { depth: number; parent: string | null }> {
  const out = new Map<string, { depth: number; parent: string | null }>();
  const stack: string[] = [];
  let bodySeen = false;
  for (const match of text.matchAll(/<(\/?)section(?:\s+id="([^"]*)")?[^>]*>|<body[^>]*>/g)) {
    if (match[0].startsWith('<body')) {
      bodySeen = true;
      continue;
    }
    if (!bodySeen) continue;
    if (match[1] === '/') {
      stack.pop();
      continue;
    }
    const id = match[2] ?? `anon-${out.size}`;
    out.set(id, { depth: stack.length + 1, parent: stack[stack.length - 1] ?? null });
    stack.push(id);
  }
  return out;
}

async function saveAs(core: CoreHandle, page: Page, file: string): Promise<string> {
  await core.enqueueDialog('dialog.saveFile', { path: file, encoding: 'utf-8' });
  await page.getByTestId('menu-file').click();
  await page.getByTestId('menu-file-saveAs').click();
  await expect(page.getByTestId('status-message')).toContainText(/saved|found/i);
  return readFileSync(file, 'utf8');
}

async function validateFile(core: CoreHandle, file: string): Promise<ValidationJson> {
  const opened = await core.rpcJob<{ document: { docId: string } }>('doc.open', { path: file });
  const report = await core.rpcJob<ValidationJson>('doc.validate', {
    docId: opened.document.docId,
    document: opened.document,
  });
  await core.rpc('doc.close', { docId: opened.document.docId });
  return report;
}

test.describe('US5 - navigate and restructure with the Document Tree', () => {
  let dir: string;
  let book = '';

  test.beforeAll(() => {
    dir = mkdtempSync(path.join(tmpdir(), 'mfbe-us5-'));
    book = path.join(dir, 'sections.fb2');
    const result = spawnSync('python3', [GENERATOR, '--out', book, '--sections', '300'], {
      encoding: 'utf8',
    });
    if (result.status !== 0 || !existsSync(book)) book = '';
    else numbering = indexFixture(readFileSync(book, 'utf8'));
  });

  test.afterAll(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  test.beforeEach(async ({ core }) => {
    test.skip(!core.hasCore, 'needs mfbe-core (MFBE_CORE_BIN)');
    test.skip(!book, 'python3 / the fixture generator are not available');
    test.skip(!(await supportsDocuments(core)), 'the core does not implement doc.* yet');
  });

  test('1. tree selection moves the Body window and the tree follows the Body caret', async ({
    core,
    page,
  }) => {
    await openBook(core, page, book);
    const tree = page.getByTestId('tree-content');
    expect(Number(await tree.getAttribute('data-section-count'))).toBeGreaterThanOrEqual(300);
    expect(Number(await tree.getAttribute('data-row-count'))).toBeGreaterThan(300);
    // Virtualised: only a slice of the rows is in the DOM.
    expect(await tree.getByRole('treeitem').count()).toBeLessThan(
      Number(await tree.getAttribute('data-row-count')),
    );
    await expect(page.getByTestId('body-view')).toHaveAttribute('data-whole-book', 'false');
    await expect(page.getByTestId('panel-body-document')).toHaveAttribute(
      'data-section-start',
      '0',
    );

    // A section deep in the book: the window moves there and the caret lands in it.
    const row = await rowOfSection(page, 250);
    await row.click();
    await expect(row).toHaveAttribute('data-selected', 'true');
    const start = Number(
      await page.getByTestId('panel-body-document').getAttribute('data-section-start'),
    );
    expect(start).toBeGreaterThan(0);
    await expect(page.getByTestId('status-path')).toContainText(/^body\[1\]\/section\[\d+\]/);
    const editor = page.getByTestId('body-editor');
    await expect(editor.locator('.fb-section[data-id="s250"]')).toBeVisible();

    // Enter opens the element in the Body view with the focus there.
    await page.getByTestId('tree-content').focus();
    await page.keyboard.press('Enter');
    await expect(editor).toBeFocused();

    // Clicking into a paragraph of another mounted section highlights that section in the tree
    // (the title paragraph would select the title row, so a body paragraph is used).
    const paragraph = editor.locator('.fb-section > p.fb-p').last();
    const paragraphSection = await paragraph.evaluate((node) =>
      node.closest('.fb-section')!.getAttribute('data-id')!,
    );
    expect(paragraphSection).not.toBe('s250');
    await paragraph.click({ position: { x: 8, y: 8 } });
    const selected = page.locator('[data-testid^="tree-row-"][data-selected="true"]');
    await expect(selected).toHaveCount(1);
    const otherRow = await rowOfSection(page, Number(paragraphSection.slice(1)));
    await expect(otherRow).toHaveAttribute('data-selected', 'true');
    // The previously selected row (virtualised away) is no longer the selection.
    const otherTestId = (await otherRow.getAttribute('data-testid'))!;
    await expect(tree).toHaveAttribute('data-selected-id', otherTestId.replace('tree-row-', ''));

    // Keyboard navigation in the tree moves the Body selection as well.
    await page.getByTestId('tree-content').focus();
    await page.keyboard.press('ArrowDown');
    await expect(otherRow).not.toHaveAttribute('data-selected', 'true');
    await expect(page.locator('[data-testid^="tree-row-"][data-selected="true"]')).toHaveCount(1);
  });

  test('2. Move Right / With Children / Left / Merge / Delete keep the structure valid', async ({
    core,
    page,
  }) => {
    await openBook(core, page, book);
    const original = structureOf(readFileSync(book, 'utf8'));
    // Two consecutive top-level parts: the second has nested chapters.
    const parts = [...original.entries()].filter(([, info]) => info.depth === 1).map(([id]) => id);
    const second = parts[1]!;
    const secondNumber = Number(second.slice(1));
    const chaptersOfSecond = [...original.entries()]
      .filter(([, info]) => info.parent === second)
      .map(([id]) => id);
    expect(chaptersOfSecond.length).toBeGreaterThan(0);

    // Move Right (one): the part becomes a child of the first part; its chapters follow it.
    await (await rowOfSection(page, secondNumber)).click();
    await expect(page.getByTestId('tree-toolbar-right')).toBeEnabled();
    await expect(page.getByTestId('tree-toolbar-left')).toBeDisabled();
    await page.getByTestId('tree-toolbar-right').click();
    await expect(page.getByTestId('status-message')).toHaveText('Section moved.');
    let row = await rowOfSection(page, secondNumber);
    await expect(row).toHaveAttribute('data-depth', '2');
    const firstChapterRow = await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)));
    await expect(firstChapterRow).toHaveAttribute('data-depth', '2');

    // Undo restores the top-level part (one undo entry).
    await page.getByTestId('menu-edit').click();
    await page.getByTestId('menu-edit-undo').click();
    row = await rowOfSection(page, secondNumber);
    await expect(row).toHaveAttribute('data-depth', '1');
    const firstChapterBack = await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)));
    await expect(firstChapterBack).toHaveAttribute('data-depth', '2');

    // Move With Children through the context menu: the whole subtree goes one level down.
    await row.click({ button: 'right' });
    await expect(page.getByTestId('tree-menu')).toBeVisible();
    await page.getByTestId('tree-menu-moveWithChildren').click();
    await expect(page.getByTestId('status-message')).toHaveText('Section moved.');
    row = await rowOfSection(page, secondNumber);
    await expect(row).toHaveAttribute('data-depth', '2');
    const nestedChapter = await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)));
    await expect(nestedChapter).toHaveAttribute('data-depth', '3');

    // Move Left lifts it back to the top level (its following siblings become its children).
    await row.click();
    await expect(page.getByTestId('tree-toolbar-left')).toBeEnabled();
    await page.getByTestId('tree-toolbar-left').click();
    await expect(page.getByTestId('status-message')).toHaveText('Section moved.');
    row = await rowOfSection(page, secondNumber);
    await expect(row).toHaveAttribute('data-depth', '1');

    // Merge the first chapter of the part with the next one.
    const firstChapter = await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)));
    await firstChapter.click();
    if (chaptersOfSecond.length > 1) {
      await expect(page.getByTestId('tree-toolbar-merge')).toBeEnabled();
      await page.getByTestId('tree-toolbar-merge').click();
      await expect(page.getByTestId('status-message')).toHaveText('Sections merged.');
      await expect(
        page.getByTestId(
          (await (
            await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)))
          ).getAttribute('data-testid'))!,
        ),
      ).toBeVisible();
    }

    // Delete the (merged) chapter after confirmation.
    const toDelete = await rowOfSection(page, Number(chaptersOfSecond[0]!.slice(1)));
    const deletedTestId = await toDelete.getAttribute('data-testid');
    await toDelete.click();
    await page.getByTestId('tree-toolbar-delete').click();
    const confirm = page.getByTestId('tree-delete-confirm');
    await expect(confirm).toContainText('Delete selected node?');
    await page.getByTestId('tree-delete-confirm-button-yes').click();
    await expect(page.getByTestId(deletedTestId!)).toHaveCount(0);
    await expect(page.getByTestId('status-message')).toHaveText('Element deleted.');

    // The saved book is schema-valid and reflects the new structure.
    const saved = path.join(dir, 'restructured.fb2');
    const xml = await saveAs(core, page, saved);
    const report = await validateFile(core, saved);
    expect(report.issues.filter((issue) => issue.severity === 'error')).toEqual([]);
    const after = structureOf(xml);
    expect(after.get(second)?.depth).toBe(1);
    expect(after.has(chaptersOfSecond[0]!)).toBe(false);
    expect(after.size).toBeLessThan(original.size);
  });

  test('3. View Source opens the Source view positioned on the element', async ({ core, page }) => {
    await openBook(core, page, book);
    const row = await rowOfSection(page, 120);
    await row.click({ button: 'right' });
    await page.getByTestId('tree-menu-viewSource').click();
    await expect(page.getByTestId('source-view')).toHaveAttribute('data-status', 'ready');
    const activeLine = page.locator('.mfbe-source-editor .cm-activeLine').first();
    await expect(activeLine).toContainText('<section id="s120">');

    // Back in the Body view the tree still works: View on a row switches the view.
    await page.getByTestId('view-body').click();
    await expect(page.getByTestId('body-editor')).toBeVisible();
    const another = await rowOfSection(page, 7);
    await another.dblclick();
    await expect(page.getByTestId('body-editor')).toBeFocused();
    await expect(
      page.getByTestId('body-editor').locator('.fb-section[data-id="s7"]'),
    ).toBeVisible();
  });
});
